package com.taller.portal.config;
import com.taller.portal.repository.UserRepository; import com.taller.portal.service.JwtService; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
/** Lee el JWT Bearer, carga el usuario activo y coloca su rol en Spring Security. */
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; /** @param jwt servicio de firma JWT @param users repositorio de usuarios. */ public JwtAuthenticationFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;} /** @param request solicitud HTTP @param response respuesta HTTP @param chain cadena de filtros @throws ServletException si falla el contenedor @throws IOException si falla I/O. */ @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String header=request.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){try{String email=jwt.email(header.substring(7));users.findByEmail(email).filter(u->u.activo).ifPresent(u->{var auth=new UsernamePasswordAuthenticationToken(u.email,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.rol.nombre.name())));SecurityContextHolder.getContext().setAuthentication(auth);});}catch(Exception ignored){}}chain.doFilter(request,response);} }
